fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut seed: i32 = host::display::state_get(1);
    if seed == 0 { seed = 31337; }
    if down == 1 && prev == 0 {
        seed = seed * 1103515245 + 12345;
        host::display::state_set(1, seed);
    }
    host::display::state_set(0, down);
    let pal = [0x101018, 0x1f3a5f, 0x3f6fa8, 0x77aadd, 0xd0e4f7, 0xe8c170, 0xa85f38, 0x5a2e2e];
    let cell: i32 = 8;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    let mut by: i32 = 0;
    while by < rows {
        let mut bx: i32 = 0;
        while bx < cols {
            let mut fx: i32 = bx;
            if bx >= cols / 2 { fx = cols - 1 - bx; }
            let mut fy: i32 = by;
            if by >= rows / 2 { fy = rows - 1 - by; }
            let mut a: i32 = fx;
            let mut b: i32 = fy;
            if b > a {
                let tmp: i32 = a;
                a = b;
                b = tmp;
            }
            let mut hsh: i32 = seed + a * 7919 + b * 104729;
            hsh = hsh * 1103515245 + 12345;
            host::display::fill_rect(bx * cell, by * cell, cell, cell, pal[(hsh >> 16) & 7]);
            bx = bx + 1;
        }
        by = by + 1;
    }
    host::display::present();
}
